WITH gaps AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) > INTERVAL '60' DAY THEN 1 ELSE 0 END AS new_group_flag FROM web_events), islands AS (SELECT id, session_id, event_type, event_time, SUM(new_group_flag) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT session_no, PERCENTILE_APPROX(session_no, 0.5) AS session_no_p50, MIN(event_time) AS started_at, PERCENTILE_APPROX(session_no, 0.5) AS session_no_p50_2, COUNT(DISTINCT event_type) AS distinct_event_types, MAX(event_time) AS last_seen FROM islands GROUP BY session_no ORDER BY session_no DESC
